/**
 * Header that signals the Mistral API (and any request-logging middleware) to
 * suppress logging of request/response bodies, keeping prompts and completions
 * out of external logs.
 */
const SILENT_HEADER = { 'x-promptfoo-silent': 'true' } as const;

/**
 * Deterministically hash a value into a 64-character lowercase hex string.
 * Plain SHA-256 (no per-session salt) so keys are stable across module reloads.
 */
function hashComponent(value: string): string {
  return crypto.createHash('sha256').update(value).digest('hex');
}

/**
 * Build a cache key that never embeds raw secrets or request content. Each of
 * the distinct request components (params/body, resolved API key, resolved API
 * base URL) is hashed separately so the key isolates entries by API key while
 * keeping the plaintext out of the (potentially on-disk) cache.
 */
function buildMistralCacheKey(
  kind: 'chat' | 'embedding',
  modelName: string,
  paramsOrBody: unknown,
  apiKey: string,
  apiBaseUrl: string,
): string {
  const paramsHash = hashComponent(JSON.stringify(paramsOrBody));
  const apiKeyHash = hashComponent(apiKey);
  const apiUrlHash = hashComponent(apiBaseUrl);
  return `mistral:${kind}:${modelName}:${paramsHash}:${apiKeyHash}:${apiUrlHash}`;
}

